/** Resolves a keydown to a command, ignoring keys typed into fields. */
export function commandForKey(event: KeyboardEvent): Command | undefined {
  const target = event.target as HTMLElement | null;
  if (target?.closest("input, textarea, [contenteditable]")) return undefined;
  const mod = event.metaKey || event.ctrlKey ? "mod+" : "";
  return commands.find((command) => command.shortcut === `${mod}${event.key.toLowerCase()}`);
}

export const DEFAULT_SHORTCUTS: Record<CommandId, Shortcut> = { "trip.new": { key: "n", mod: true }, "place.pin": { key: "p", mod: true }, "view.help": { key: "?", mod: false }, "trip.share": { key: "s", mod: true, shift: true } }; // finalIdentifierOnWideLine
